{
  "claims": [
    {
      "claim_text": "Freshness in HTTP caching is primarily determined by explicit expiration times that the origin server assigns using the Expires header or the max-age response directive.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 states the primary mechanism for determining freshness is for an origin server to provide an explicit expiration time using either the Expires header field or the max-age response directive.",
      "citations": [
        {
          "index": 0,
          "quote": "The primary mechanism for determining freshness is for an origin server to provide an explicit expiration time in the future, using either the Expires header field (Section 5.3) or the max-age response directive (Section 5.2.2.1)."
        }
      ]
    },
    {
      "claim_text": "Explicit expiration times reflect the server's belief that the representation will not change in a semantically significant way before that time.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 states origin servers assign future explicit expiration times in the belief that the representation is not likely to change in a semantically significant way before the expiration time.",
      "citations": [
        {
          "index": 0,
          "quote": "Generally, origin servers will assign future explicit expiration times to responses in the belief that the representation is not likely to change in a semantically significant way before the expiration time is reached."
        }
      ]
    },
    {
      "claim_text": "When no explicit expiration is present, a cache may apply a heuristic to estimate a plausible expiration time.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 1 states a cache MAY assign a heuristic expiration time when an explicit time is not specified.",
      "citations": [
        {
          "index": 1,
          "quote": "Since origin servers do not always provide explicit expiration times, a cache MAY assign a heuristic expiration time when an explicit time is not specified, employing algorithms that use other field values (such as the Last-Modified time) to estimate a plausible expiration time."
        }
      ]
    },
    {
      "claim_text": "A cache must not use heuristics when an explicit time exists.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 states a cache MUST NOT use heuristics to determine freshness when an explicit expiration time is present.",
      "citations": [
        {
          "index": 2,
          "quote": "A cache MUST NOT use heuristics to determine freshness when an explicit expiration time is present in the stored response."
        }
      ]
    },
    {
      "claim_text": "Heuristics are only allowed for status codes defined as heuristically cacheable or responses explicitly marked cacheable (for example, with the public directive).",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 states heuristics can only be used on responses without explicit freshness whose status codes are defined as heuristically cacheable and on responses without explicit freshness marked as explicitly cacheable (e.g., with a public response directive).",
      "citations": [
        {
          "index": 2,
          "quote": "Because of the requirements in Section 3, heuristics can only be used on responses without explicit freshness whose status codes are defined as \"heuristically cacheable\" (e.g., see Section 15.1 of [HTTP]) and on responses without explicit freshness that have been marked as explicitly cacheable (e.g., with a public response directive)."
        }
      ]
    },
    {
      "claim_text": "A common heuristic uses the Last-Modified time, with the expiration set to no more than a fraction of the interval since that time, typically 10%.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 3 encourages caches to use a heuristic expiration value no more than some fraction of the interval since the Last-Modified time, with a typical setting of 10%.",
      "citations": [
        {
          "index": 3,
          "quote": "If the response has a Last-Modified header field (Section 8.8.2 of [HTTP]), caches are encouraged to use a heuristic expiration value that is no more than some fraction of the interval since that time. A typical setting of this fraction might be 10%."
        }
      ]
    },
    {
      "claim_text": "The unqualified no-cache response directive means the response must not be used to satisfy any other request without first forwarding it to the origin for validation and receiving a successful response.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 8 states the unqualified no-cache response directive indicates the response MUST NOT be used to satisfy any other request without forwarding it for validation and receiving a successful response.",
      "citations": [
        {
          "index": 8,
          "quote": "The no-cache response directive, in its unqualified form (without an argument), indicates that the response MUST NOT be used to satisfy any other request without forwarding it for validation and receiving a successful response; see Section 4.3."
        }
      ]
    },
    {
      "claim_text": "The no-cache request directive signals that the client prefers a stored response not be used without successful validation.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 5 states the no-cache request directive indicates the client prefers a stored response not be used to satisfy the request without successful validation on the origin server.",
      "citations": [
        {
          "index": 5,
          "quote": "The no-cache request directive indicates that the client prefers a stored response not be used to satisfy the request without successful validation on the origin server."
        }
      ]
    },
    {
      "claim_text": "The no-store directive requires that a cache not store any part of either the request or the response and not use the response to satisfy any other request at all.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 9 states the no-store response directive indicates a cache MUST NOT store any part of either the immediate request or the response and MUST NOT use the response to satisfy any other request.",
      "citations": [
        {
          "index": 9,
          "quote": "The no-store response directive indicates that a cache MUST NOT store any part of either the immediate request or the response and MUST NOT use the response to satisfy any other request."
        }
      ]
    },
    {
      "claim_text": "The must-revalidate response directive requires that once a response becomes stale, a cache must not reuse it until it has been successfully revalidated by the origin.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 6 states the must-revalidate response directive indicates that once the response has become stale, a cache MUST NOT reuse that response until it has been successfully validated by the origin.",
      "citations": [
        {
          "index": 6,
          "quote": "The must-revalidate response directive indicates that once the response has become stale, a cache MUST NOT reuse that response to satisfy another request until it has been successfully validated by the origin, as defined by Section 4.3."
        }
      ]
    },
    {
      "claim_text": "A cache must never ignore the must-revalidate directive—even when disconnected, it must generate an error response, typically 504 (Gateway Timeout), rather than serve the stale response.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 7 states in all circumstances a cache MUST NOT ignore the must-revalidate directive; if disconnected, it MUST generate an error response rather than reuse the stale response, and the status code SHOULD be 504 (Gateway Timeout).",
      "citations": [
        {
          "index": 7,
          "quote": "In all circumstances, a cache MUST NOT ignore the must-revalidate directive; in particular, if a cache is disconnected, the cache MUST generate an error response rather than reuse the stale response. The generated status code SHOULD be 504 (Gateway Timeout) unless another error status code is more applicable."
        }
      ]
    },
    {
      "claim_text": "The unqualified private directive indicates the response is intended for a single user, so a shared cache must not store it.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 10 states the unqualified private response directive indicates a shared cache MUST NOT store the response (i.e., the response is intended for a single user).",
      "citations": [
        {
          "index": 10,
          "quote": "The unqualified private response directive indicates that a shared cache MUST NOT store the response (i.e., the response is intended for a single user)."
        }
      ]
    },
    {
      "claim_text": "A private (browser) cache may store the response even if it would not otherwise be heuristically cacheable.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 10 states a private cache MAY store the response, subject to Section 3 constraints, even if the response would not otherwise be heuristically cacheable by a private cache.",
      "citations": [
        {
          "index": 10,
          "quote": "It also indicates that a private cache MAY store the response, subject to the constraints defined in Section 3, even if the response would not otherwise be heuristically cacheable by a private cache."
        }
      ]
    },
    {
      "claim_text": "s-maxage applies specifically to shared caches, specifying a maximum age that overrides whatever freshness lifetime was indicated by max-age or the Expires header.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 11 states the s-maxage response directive indicates that, for a shared cache, the maximum age specified by this directive overrides the maximum age specified by either the max-age directive or the Expires header field.",
      "citations": [
        {
          "index": 11,
          "quote": "The s-maxage response directive indicates that, for a shared cache, the maximum age specified by this directive overrides the maximum age specified by either the max-age directive or the Expires header field."
        }
      ]
    },
    {
      "claim_text": "Together, these directives give origin servers and clients fine-grained control over whether responses are stored, when they must be revalidated, and how long different classes of cache may consider them fresh.",
      "verdict": "UNSUPPORTED",
      "reasoning": "This is a general summarizing statement not directly stated in any passage; the passages describe individual directives but do not make this overall characterization.",
      "citations": []
    }
  ]
}
